script:
frappe.ui.form.on('Cash Book Entry', {
    setup: function(frm) {
        frm.set_query('account', function() {
            console.log("Custom Account query fired!", frm.doc.company);
            return {
                filters: {
                    account_type: ['in', ['Bank', 'Cash']],
                    is_group: 0,
                    disabled: 0,
                    company: frm.doc.company
                }
            };
        });
    }
});

frappe.ui.form.on('Cash Book Account', {
    // This triggers automatically whenever a new row is added
    accounting_entries_add: function(frm, cdt, cdn) {
        console.log("New row added to Cash Book Account table!");
        let rows = frm.doc.accounting_entries || [];

        if (rows.length > 1) {
            let previous_row = rows[rows.length - 2];
            let new_row = locals[cdt][cdn];

            // Copy previous post_date and reference_date
            new_row.post_date = previous_row.post_date;
            new_row.reference_date = previous_row.reference_date;

            frm.refresh_field('accounting_entries');
            console.log("Copied date from previous row:", previous_row.post_date);
        }
    }
});
